/**
 * Shared Current / Proposed snippet resolution for Quality assess + remediation.
 * Prefers quality.proposals.diffHunk; falls back to demo rule maps.
 */
import type { AiProposal, QualityViolation } from './qualityDemoData';

export type ProposalView = {
  explanation: string;
  current: string[];
  proposed: string[];
  /** 0–1 AI confidence when available from quality.proposals */
  confidence?: number;
};

