export function parseDiffHunk(hunk: string): { current: string[]; proposed: string[] } {
  const current: string[] = [];
  const proposed: string[] = [];
  hunk.split('\n').forEach(line => {
    if (line.startsWith('---') || line.startsWith('+++') || line.startsWith('@@')) return;
    if (line.startsWith('-')) current.push(line.slice(1));
    else if (line.startsWith('+')) proposed.push(line.slice(1));
    else if (line.startsWith(' ')) {
      const text = line.slice(1);
      current.push(text);
      proposed.push(text);
    }
  });
  return { current, proposed };
}

export function proposalFor(
  v: QualityViolation,
  proposals: AiProposal[] | undefined,
): ProposalView | null {
  const fromQuality =
    proposals?.find(
      p => p.ruleId === v.ruleId && p.file === v.file && p.lineStart === v.lineStart,
    ) ?? proposals?.find(p => p.ruleId === v.ruleId);
  if (fromQuality?.diffHunk) {
    const { current, proposed } = parseDiffHunk(fromQuality.diffHunk);
    if (current.length || proposed.length) {
      return {
        explanation: fromQuality.explanation || fromQuality.suggestion || '',
        current,
        proposed,
        confidence:
          typeof fromQuality.confidence === 'number' ? fromQuality.confidence : undefined,
      };
    }
  }
  const fallback = FALLBACK_PROPOSALS[v.ruleId];
  if (fallback) return fallback;
  if (v.aiSuggestion) {
    return {
      explanation: v.aiReason || v.aiSuggestion,
      current: [`# ${v.file}:${v.lineStart}`, v.message],
      proposed: [v.aiSuggestion],
    };
  }
  return null;
}

/** Current-only lines for assess / review (no Proposed until remediation). */
export function currentSnippetFor(
  v: QualityViolation,
  proposals: AiProposal[] | undefined,
): string[] {
  return proposalFor(v, proposals)?.current ?? [];
}
