/**
 * Short display codes for Assess rows (SPA-style L046 / M001).
 * Canonical `ruleId` stays the ansible-lint / engine id for data + proposals.
 */
/** Demo display codes — production uses engine short ids when available. */
const RULE_DISPLAY_CODES: Record<string, string> = {
  'SEC-001': 'SEC-001',
  'DEP-CVE-001': 'CVE-001',
  'risky-file-permissions': 'RFP001',
  'aap-deprecated-syntax': 'AAP001',
  'aap-deprecated-module': 'AAP002',
  'fqcn[action-core]': 'FQCN',
  'command-instead-of-shell': 'L046',
  'no-changed-when': 'L013',
  'name[missing]': 'name',
  'jinja[spacing]': 'jinja',
};

export function ruleDisplayCode(ruleId: string): string {
  if (RULE_DISPLAY_CODES[ruleId]) return RULE_DISPLAY_CODES[ruleId];
  // Already compact (e.g. L046, M001) — show as-is
  if (/^[A-Z]{1,4}-?\d{2,4}$/i.test(ruleId) || ruleId.length <= 8) return ruleId;
  // Fallback: first segment before [ or truncate
  const bare = ruleId.split('[')[0] ?? ruleId;
  return bare.length > 10 ? `${bare.slice(0, 8)}…` : bare;
}
