type FixType = 'quick-fix' | 'ai' | 'manual';
type Decision = 'accepted' | 'declined' | 'pending';
type StepId = 'quick-fix' | 'ai' | 'commit';

const SEVERITY_ORDER: SeverityClass[] = ['critical', 'high', 'medium', 'low', 'info'];

const DECISION_ORDER: Decision[] = ['pending', 'accepted', 'declined'];
const DECISION_LABELS: Record<Decision, string> = {
  pending: 'Undecided',
  accepted: 'Accepted',
  declined: 'Declined',
};

const KIND_LABELS: Record<string, string> = {
  task: 'Task',
  play: 'Play',
  role: 'Role',
  playbook: 'Playbook',
  collection: 'Collection',
  block: 'Block',
  inventory: 'Inventory',
};

const STEP_META: { id: StepId; label: string }[] = [
  { id: 'quick-fix', label: 'Quick-fix' },
  { id: 'ai', label: 'AI' },
  // Internal id stays `commit` (SPA/ADR contract); Portal label is outcome-oriented
  { id: 'commit', label: 'Open pull request' },
];

function defaultRemediationBranch(scanCommit?: string): string {
  const suffix = (scanCommit || 'fix').replace(/[^a-zA-Z0-9]/g, '').slice(0, 8) || 'fix';
  return `apme/remediate-${suffix}`;
}

function firstStep(quickFixCount: number, hasAi: boolean): StepId {
  if (quickFixCount > 0) return 'quick-fix';
  if (hasAi) return 'ai';
  return 'commit';
}

function violationKey(v: QualityViolation): string {
  return `${v.ruleId}:${v.file}:${v.lineStart}`;
}

function fixTypeOf(v: QualityViolation): FixType {
  if (v.fixTier === 'deterministic') return 'quick-fix';
  if (v.fixTier === 'ai') return 'ai';
  return 'manual';
}

function locationKey(v: QualityViolation): string {
  const path = (v.yamlPath || '').trim();
  return path || v.file || 'Not tied to a location';
}

function kindLabel(scope: string): string {
  return KIND_LABELS[scope] ?? scope.charAt(0).toUpperCase() + scope.slice(1);
}

