function ProposalDiff({
  proposal,
  classes,
  isDark,
}: {
  proposal: ProposalView;
  classes: ReturnType<typeof useStyles>;
  isDark: boolean;
}) {
  const removedBg = isDark ? 'rgba(201,25,11,0.18)' : '#fcebeb';
  const addedBg = isDark ? 'rgba(62,134,53,0.18)' : '#e7f5e7';
  return (
    <Box className={classes.proposalBox}>
      {proposal.explanation ? (
        <Typography className={classes.proposalExplainer}>{proposal.explanation}</Typography>
      ) : null}
      <Box className={classes.diffGrid}>
        <Box className={classes.diffPane}>
          <Typography className={classes.diffPaneTitle}>Current</Typography>
          {proposal.current.length === 0 ? (
            <Typography className={classes.diffLine} style={{ opacity: 0.6 }}>
              (no lines)
            </Typography>
          ) : (
            proposal.current.map((line, i) => (
              <Typography
                key={`c-${i}`}
                className={classes.diffLine}
                style={{ backgroundColor: removedBg }}
              >
                {line || ' '}
              </Typography>
            ))
          )}
        </Box>
        <Box className={classes.diffPane}>
          <Typography className={classes.diffPaneTitle}>Proposed</Typography>
          {proposal.proposed.length === 0 ? (
            <Typography className={classes.diffLine} style={{ opacity: 0.6 }}>
              (removed)
            </Typography>
          ) : (
            proposal.proposed.map((line, i) => (
              <Typography
                key={`p-${i}`}
                className={classes.diffLine}
                style={{ backgroundColor: addedBg }}
              >
                {line || ' '}
              </Typography>
            ))
          )}
        </Box>
      </Box>
    </Box>
  );
}

export type RemediationFinishResult = {
  branchName: string;
  commitSha: string;
  prUrl: string | null;
  acceptedKeys: string[];
  /** Keys the user Declined during remediation (read-only Assess end state). */
  declinedKeys: string[];
};

export type RemediationFinishOptions = {
  /** Leave Complete and start a new remediation session (e.g. Remediate remaining). */
  reopenRemediate?: boolean;
};

export type RemediationWorkspaceProps = {
  quality: ProjectQualityData;
  repositoryName: string;
  isResume?: boolean;
  /** Leave without completing (abandons ephemeral session from UI perspective). */
  onBack: () => void;
  /**
   * Sync durable result to parent without leaving (keeps green stepper + Assess embed).
   */
  onCommitted?: (result: RemediationFinishResult) => void;
  /** Leave after push/PR — parent shows durable Assess (or reopens remediation). */
  onFinished?: (result: RemediationFinishResult, options?: RemediationFinishOptions) => void;
};

export const RemediationWorkspace = ({
  quality,
  repositoryName,
  isResume = false,
  onBack,
  onCommitted,
  onFinished,
}: RemediationWorkspaceProps) => {
  const classes = useStyles();
  const theme = useTheme();
  const isDark = theme.palette.type === 'dark';
  const violations = quality.violations ?? [];

  const quickFixItems = useMemo(() => violations.filter(v => fixTypeOf(v) === 'quick-fix'), [violations]);
  const aiItems = useMemo(() => violations.filter(v => fixTypeOf(v) === 'ai'), [violations]);
  const manualItems = useMemo(() => violations.filter(v => fixTypeOf(v) === 'manual'), [violations]);

  const hasAi = aiItems.length > 0;
  const hasQuickFix = quickFixItems.length > 0;

  const [step, setStep] = useState<StepId>(() => firstStep(quickFixItems.length, hasAi));
  const [decisions, setDecisions] = useState<Map<string, Decision>>(() => {
    const map = new Map<string, Decision>();
    // Resume demo: pre-accept a couple of quick-fixes
    if (isResume) {
      quickFixItems.slice(0, 2).forEach(v => map.set(violationKey(v), 'accepted'));
    }
    return map;
  });
  const [aiConfirmOpen, setAiConfirmOpen] = useState(false);
  const [severityFilters, setSeverityFilters] = useState<Set<SeverityClass>>(
    () => new Set(SEVERITY_ORDER.filter(s => violations.some(v => v.severity === s))),
  );
  const [decisionFilters, setDecisionFilters] = useState<Set<Decision>>(
    () => new Set(DECISION_ORDER),
  );
  // Collapsed by default — rule / fix-type / kind badges stay scannable (SPA pattern)
  const [expanded, setExpanded] = useState<Set<string>>(() => new Set());
  const [branchName, setBranchName] = useState(() =>
    defaultRemediationBranch(quality.lastScannedCommit),
  );
  const [openPullRequest, setOpenPullRequest] = useState(true);
  const [pushResult, setPushResult] = useState<{
    branchName: string;
    commitSha: string;
    prUrl: string | null;
  } | null>(null);

  const pushed = Boolean(pushResult);

  const visibleSteps = useMemo(() => {
    return STEP_META.filter(s => {
      if (s.id === 'quick-fix') return hasQuickFix;
      if (s.id === 'ai') return hasAi;
      return true;
    });
  }, [hasAi, hasQuickFix]);

  const stepIndex = visibleSteps.findIndex(s => s.id === step);

  const gateItems = step === 'quick-fix' ? quickFixItems : step === 'ai' ? aiItems : [];

  const decisionOf = (v: QualityViolation): Decision =>
    decisions.get(violationKey(v)) ?? 'pending';

  const filtered = useMemo(
    () =>
      gateItems.filter(v => {
        if (severityFilters.size > 0 && !severityFilters.has(v.severity)) return false;
        if (decisionFilters.size > 0 && !decisionFilters.has(decisionOf(v))) return false;
        return true;
      }),
    // decisionOf reads decisions map
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [gateItems, severityFilters, decisionFilters, decisions],
  );

  /** Severity facets respect the decision filter slice. */
  const byDecision = useMemo(
    () =>
      gateItems.filter(
        v => decisionFilters.size === 0 || decisionFilters.has(decisionOf(v)),
      ),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [gateItems, decisionFilters, decisions],
  );
  /** Decision facets respect the severity filter slice. */
  const bySeverity = useMemo(
    () =>
      gateItems.filter(
        v => severityFilters.size === 0 || severityFilters.has(v.severity),
      ),
    [gateItems, severityFilters],
  );

  const presentSeverities = useMemo(
    () => SEVERITY_ORDER.filter(s => gateItems.some(v => v.severity === s)),
    [gateItems],
  );
  const severityCounts = useMemo(() => {
    const counts = {} as Record<SeverityClass, number>;
    presentSeverities.forEach(sev => {
      counts[sev] = byDecision.filter(v => v.severity === sev).length;
    });
    return counts;
  }, [byDecision, presentSeverities]);
  const severityTotal = presentSeverities.reduce((sum, sev) => sum + severityCounts[sev], 0);
  // Empty set = no filter (show all). Narrowed only when a non-empty subset is selected.
  const severityNarrowed =
    severityFilters.size > 0 && presentSeverities.some(s => !severityFilters.has(s));

  const decisionCounts = useMemo(() => {
    const counts = { pending: 0, accepted: 0, declined: 0 } as Record<Decision, number>;
    bySeverity.forEach(v => {
      counts[decisionOf(v)] += 1;
    });
    return counts;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [bySeverity, decisions]);
  const decisionNarrowed =
    decisionFilters.size > 0 && DECISION_ORDER.some(d => !decisionFilters.has(d));

  const toggleSeverity = (sev: SeverityClass) => {
    setSeverityFilters(prev => {
      const next = new Set(prev);
      if (next.has(sev)) next.delete(sev);
      else next.add(sev);
      // Empty set = no severity filter (show all)
      return next;
    });
  };

  const toggleDecision = (d: Decision) => {
    setDecisionFilters(prev => {
      const next = new Set(prev);
      if (next.has(d)) next.delete(d);
      else next.add(d);
      // Empty set = no decision filter (show all)
      return next;
    });
  };

  const filtersActive = severityNarrowed || decisionNarrowed;
  const clearAllFilters = () => {
    setSeverityFilters(new Set(presentSeverities));
    setDecisionFilters(new Set(DECISION_ORDER));
  };

  const expandAll = () => {
    setExpanded(new Set(groups.map(g => g.key)));
  };

  const collapseAll = () => {
    setExpanded(new Set());
  };

  const groups = useMemo(() => {
    const byLoc = new Map<string, QualityViolation[]>();
    filtered.forEach(v => {
      const key = locationKey(v);
      const list = byLoc.get(key) ?? [];
      list.push(v);
      byLoc.set(key, list);
    });
    return [...byLoc.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, items]) => ({ key, title: key, findings: items }));
  }, [filtered]);

  /** Remediation steps: drawers open by default when the list changes. */
  const groupKeySig = useMemo(() => groups.map(g => g.key).join('\0'), [groups]);
  useEffect(() => {
    setExpanded(new Set(groups.map(g => g.key)));
  }, [groupKeySig]); // eslint-disable-line react-hooks/exhaustive-deps

  const setDecision = (key: string, d: Decision) => {
    setDecisions(prev => {
      const next = new Map(prev);
      next.set(key, d);
      return next;
    });
  };

  const setPendingDecisions = (items: QualityViolation[], d: 'accepted' | 'declined') => {
    setDecisions(prev => {
      const next = new Map(prev);
      items.forEach(v => {
        const k = violationKey(v);
        if ((next.get(k) ?? 'pending') === 'pending') next.set(k, d);
      });
      return next;
    });
  };

  const clearDecisions = (items: QualityViolation[]) => {
    setDecisions(prev => {
      const next = new Map(prev);
      items.forEach(v => {
        next.set(violationKey(v), 'pending');
      });
      return next;
    });
  };

  const pendingCount = (items: QualityViolation[]) =>
    items.filter(v => (decisions.get(violationKey(v)) ?? 'pending') === 'pending').length;

  const decidedCount = (items: QualityViolation[]) =>
    items.filter(v => {
      const d = decisions.get(violationKey(v)) ?? 'pending';
      return d === 'accepted' || d === 'declined';
    }).length;

  const acceptedCount = (items: QualityViolation[]) =>
    items.filter(v => decisions.get(violationKey(v)) === 'accepted').length;

  const goNext = () => {
    // Brad rule: every finding in the gate must be Accept or Decline before Next.
    if ((step === 'quick-fix' || step === 'ai') && pendingCount(gateItems) > 0) return;
    if (step === 'quick-fix') {
      setStep(hasAi ? 'ai' : 'commit');
      return;
    }
    if (step === 'ai') {
      const acceptedAi = acceptedCount(aiItems);
      if (acceptedAi > 0) {
        setAiConfirmOpen(true);
        return;
      }
      // Nothing accepted — proceed without spending AI tokens
      setStep('commit');
    }
  };

  const confirmAiAndContinue = () => {
    setAiConfirmOpen(false);
    setStep('commit');
  };

  const skipGate = () => {
    if (step === 'quick-fix') {
      setDecisions(prev => {
        const next = new Map(prev);
        quickFixItems.forEach(v => {
          const k = violationKey(v);
          if ((next.get(k) ?? 'pending') === 'pending') next.set(k, 'declined');
        });
        return next;
      });
      setStep(hasAi ? 'ai' : 'commit');
      return;
    }
    if (step === 'ai') {
      // Escape: no AI tokens — clear all AI decisions (including prior accepts)
      setAiConfirmOpen(false);
      setDecisions(prev => {
        const next = new Map(prev);
        aiItems.forEach(v => next.set(violationKey(v), 'declined'));
        return next;
      });
      setStep('commit');
    }
  };

  const stepDescription = (() => {
    if (step === 'commit' && pushed) {
      return pushResult?.prUrl
        ? 'Next, review the pull request in Dev Spaces or open it in your source control.'
        : 'Open a pull request so reviewers can approve the accepted fixes.';
    }
    switch (step) {
      case 'quick-fix':
        return 'Review each quick-fix suggestion and Accept or Decline.';
      case 'ai':
        return 'Review each AI suggestion and Accept or Decline.';
      case 'commit':
        return 'Create a branch, push accepted fixes, and optionally open a pull request.';
      default:
        return '';
    }
  })();

  const totalAccepted =
    acceptedCount(quickFixItems) + acceptedCount(aiItems);

  const undecidedInGate =
    step === 'quick-fix' || step === 'ai' ? pendingCount(gateItems) : 0;
  const nextDisabled = undecidedInGate > 0;

  /** Short status beside the step CTA — locked state explains why Next is disabled. */
  const footerHint = (() => {
    if ((step === 'quick-fix' || step === 'ai') && nextDisabled) {
      return undecidedInGate === 1
        ? '1 undecided — Accept or Decline to continue.'
        : `${undecidedInGate} undecided — Accept or Decline to continue.`;
    }
    if (step === 'quick-fix') {
      const n = acceptedCount(quickFixItems);
      const d = quickFixItems.filter(v => decisions.get(violationKey(v)) === 'declined').length;
      return n > 0
        ? `Next applies ${n} accepted quick-fix${n === 1 ? '' : 'es'}${d > 0 ? ` (${d} declined)` : ''}.`
        : 'Next continues with no quick-fixes applied.';
    }
    if (step === 'ai') {
      const n = acceptedCount(aiItems);
      return n > 0
        ? `Next continues with ${n} accepted AI fix${n === 1 ? '' : 'es'}.`
        : 'Next continues with no AI fixes applied.';
    }
    if (step === 'commit' && !pushed) {
      return openPullRequest
        ? 'Pushes accepted fixes to a branch and opens a pull request.'
        : 'Pushes accepted fixes to a branch.';
    }
    return '';
  })();

  const acceptedKeys = useMemo(() => {
    const keys: string[] = [];
    [...quickFixItems, ...aiItems].forEach(v => {
      const k = violationKey(v);
      if (decisions.get(k) === 'accepted') keys.push(k);
    });
    return keys;
  }, [quickFixItems, aiItems, decisions]);

  const declinedKeys = useMemo(() => {
    const keys: string[] = [];
    [...quickFixItems, ...aiItems].forEach(v => {
      const k = violationKey(v);
      if (decisions.get(k) === 'declined') keys.push(k);
    });
    return keys;
  }, [quickFixItems, aiItems, decisions]);

  const buildFinishResult = (
    base: NonNullable<typeof pushResult>,
  ): RemediationFinishResult => ({
    ...base,
    acceptedKeys,
    declinedKeys,
  });

  const submitPush = () => {
    const branch = branchName.trim() || defaultRemediationBranch(quality.lastScannedCommit);
    const sha = `a1b2c3d${Math.floor(Math.random() * 10)}`;
    const base = {
      branchName: branch,
      commitSha: sha,
      prUrl: openPullRequest
        ? `https://github.com/example/${repositoryName}/pull/42`
        : null,
    };
    setPushResult(base);
    onCommitted?.(buildFinishResult(base));
  };

  const finishToQuality = (options?: RemediationFinishOptions) => {
    if (!pushResult) {
      onBack();
      return;
    }
    const result = buildFinishResult(pushResult);
    if (onFinished) onFinished(result, options);
    else onBack();
  };

  const finishResult: RemediationFinishResult | null = pushResult
    ? buildFinishResult(pushResult)
    : null;

  const showSkip = step === 'quick-fix' || step === 'ai';
  const showNext = step !== 'commit';
  const showPushAction = step === 'commit' && !pushed;
  const acceptedAiCount = acceptedCount(aiItems);
  const pushCtaLabel = openPullRequest ? 'Open pull request' : 'Push to branch';
  const pendingInView = pendingCount(filtered);
  const decidedInView = decidedCount(filtered);
  const showBulkRemaining =
    (step === 'quick-fix' || step === 'ai') && (pendingInView > 0 || decidedInView > 0);

  const actionButtons = (
    <Box className={classes.actionButtons}>
      {showSkip && (
        <Button className={classes.skipButton} onClick={skipGate}>
          Skip {step === 'ai' ? 'AI' : 'Quick-fix'}
        </Button>
      )}
      {showNext && (
        <Button
          variant="contained"
          color="primary"
          disabled={nextDisabled}
          onClick={goNext}
          className={classes.nextButton}
          endIcon={<ArrowForwardIcon style={{ fontSize: 18 }} />}
        >
          Next
        </Button>
      )}
      {showPushAction && (
        <Button
          variant="contained"
          color="primary"
          disabled={totalAccepted === 0}
          onClick={submitPush}
          className={classes.nextButton}
        >
          {pushCtaLabel}
        </Button>
      )}
    </Box>
  );

  return (
    <Box>
        <Button
          className={classes.backLink}
          startIcon={<ArrowBackIcon style={{ fontSize: 16 }} />}
          onClick={pushed ? finishToQuality : onBack}
        >
          Quality
        </Button>

        <Typography className={classes.title}>Remediation</Typography>
        <Box className={classes.subtitle} aria-label="Scan context">
          <span>Latest scan</span>
          <span aria-hidden>·</span>
          <span>{quality.lastScannedAt}</span>
          {quality.lastScannedCommit && (
            <>
              <span aria-hidden>·</span>
              <span>
                Commit <code className={classes.commitCode}>{quality.lastScannedCommit}</code>
              </span>
            </>
          )}
        </Box>

        {!pushed && (
          <Typography
            style={{
              fontSize: 12,
              color: theme.palette.text.secondary,
              marginBottom: 12,
            }}
          >
            Continuing from this scan — same session, no rescan.
          </Typography>
        )}

        {/* Compact stepper */}
        <Box className={classes.stepper} role="navigation" aria-label="Remediation steps">
          {visibleSteps.map((s, i) => {
            // After push/PR, the final step is complete — not still "current"
            const done = i < stepIndex || (s.id === 'commit' && pushed);
            const current = s.id === step && !done;
            return (
              <Box key={s.id} className={classes.stepItem}>
                {i > 0 && (
                  <span className={classes.stepConnector} aria-hidden>
                    <ArrowForwardIcon />
                  </span>
                )}
                <Box
                  className={classes.stepDot}
                  style={{
                    backgroundColor: current
                      ? theme.palette.primary.main
                      : done
                        ? '#3E8635'
                        : (isDark ? 'rgba(255,255,255,0.08)' : '#f0f0f0'),
                    color: current || done ? '#fff' : theme.palette.text.secondary,
                  }}
                >
                  {done ? <CheckIcon style={{ fontSize: 14 }} /> : i + 1}
                </Box>
                <Typography
                  className={classes.stepLabel}
                  style={{
                    color: current ? theme.palette.text.primary : theme.palette.text.secondary,
                    fontWeight: current ? 600 : 500,
                  }}
                >
                  {s.label}
                </Typography>
              </Box>
            );
          })}
        </Box>

        <Typography style={{ fontSize: 14, marginBottom: 12, lineHeight: 1.5 }}>
          {stepDescription}
        </Typography>

        {step === 'commit' && !pushed && (showNext || showSkip || showPushAction) && (
          <Box className={classes.actionsBanner} style={{ marginBottom: 16, border: `1px solid ${theme.palette.divider}`, borderRadius: 8 }}>
            <Typography className={classes.footerHint}>{footerHint}</Typography>
            {actionButtons}
          </Box>
        )}

        {step !== 'commit' && (
          <Box className={classes.workPanel}>
            {!pushed && (showNext || showSkip || showPushAction) && (
              <Box className={classes.actionsBanner}>
                <Typography className={classes.footerHint}>{footerHint}</Typography>
                {actionButtons}
              </Box>
            )}

            {step === 'ai' && (
              <Box className={classes.aiBanner} style={{ margin: '12px 16px 0' }}>
                <Typography style={{ fontSize: 13, color: theme.palette.text.secondary }}>
                  Generating accepted AI suggestions uses tokens. You confirm before any are spent.
                </Typography>
              </Box>
            )}

            <Box className={classes.filterBar} aria-label="Filters">
              {severityTotal > 0 && (
                <Box className={classes.severityBar} role="group" aria-label="Severity distribution">
                  {presentSeverities.map(sev => (
                    <Box
                      key={sev}
                      style={{
                        width: `${(severityCounts[sev] / severityTotal) * 100}%`,
                        backgroundColor: SEVERITY_COLORS[sev],
                        opacity: !severityNarrowed || severityFilters.has(sev) ? 1 : 0.25,
                        cursor: 'pointer',
                      }}
                      onClick={() => toggleSeverity(sev)}
                      title={`${sev.charAt(0).toUpperCase() + sev.slice(1)} (${severityCounts[sev]})`}
                    />
                  ))}
                </Box>
              )}
              <Box className={classes.filterControls}>
                <Box className={classes.filterGroup} role="group" aria-label="Severity filters">
                  {presentSeverities.map(sev => {
                    const selected = severityFilters.has(sev);
                    return (
                      <Chip
                        key={sev}
                        size="small"
                        variant="outlined"
                        label={`${sev.charAt(0).toUpperCase() + sev.slice(1)} (${severityCounts[sev]})`}
                        className={classes.pill}
                        onClick={() => toggleSeverity(sev)}
                        style={{
                          backgroundColor: selected ? `${SEVERITY_COLORS[sev]}22` : 'transparent',
                          color: selected ? SEVERITY_COLORS[sev] : theme.palette.text.secondary,
                          border: `1px solid ${selected ? `${SEVERITY_COLORS[sev]}88` : theme.palette.divider}`,
                          opacity: !severityNarrowed || selected ? 1 : 0.45,
                        }}
                      />
                    );
                  })}
                </Box>
                <Box
                  className={classes.filterGroup}
                  role="group"
                  aria-label="Decision filters"
                  style={{ marginLeft: 'auto' }}
                >
                  {DECISION_ORDER.map(d => {
                    const selected = decisionFilters.has(d);
                    const emphasize = decisionNarrowed && selected;
                    return (
                      <Chip
                        key={d}
                        size="small"
                        variant="outlined"
                        label={`${DECISION_LABELS[d]} (${decisionCounts[d]})`}
                        className={classes.pill}
                        onClick={() => toggleDecision(d)}
                        style={{
                          backgroundColor: emphasize
                            ? isDark
                              ? 'rgba(255,255,255,0.08)'
                              : 'rgba(0,0,0,0.06)'
                            : 'transparent',
                          color: theme.palette.text.secondary,
                          border: `1px solid ${
                            emphasize ? theme.palette.text.secondary : theme.palette.divider
                          }`,
                          opacity: !decisionNarrowed || selected ? 1 : 0.45,
                        }}
                      />
                    );
                  })}
                  {filtersActive && (
                    <Button
                      size="small"
                      color="primary"
                      onClick={clearAllFilters}
                      style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 6px' }}
                    >
                      Clear filters
                    </Button>
                  )}
                </Box>
              </Box>
            </Box>

            <Box className={classes.findingsSummaryRow}>
              <Box style={{ display: 'inline-flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
                <Typography style={{ fontSize: 13, color: theme.palette.text.secondary }}>
                  {filtersActive
                    ? `Showing ${filtered.length} of ${gateItems.length} findings`
                    : `${filtered.length} finding${filtered.length === 1 ? '' : 's'}`}
                </Typography>
                {groups.length > 0 && (
                  <>
                    <Button
                      size="small"
                      onClick={expandAll}
                      style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 4px' }}
                    >
                      Expand all
                    </Button>
                    <Button
                      size="small"
                      onClick={collapseAll}
                      style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 4px' }}
                    >
                      Collapse all
                    </Button>
                  </>
                )}
              </Box>
              {showBulkRemaining && (
                <Box className={classes.bulkListGroup} role="group" aria-label="Bulk decisions">
                  {pendingInView > 0 && (
                    <>
                      <Button
                        className={classes.bulkListBtn}
                        startIcon={<CheckIcon style={{ fontSize: 16 }} />}
                        onClick={() => setPendingDecisions(filtered, 'accepted')}
                      >
                        Accept remaining ({pendingInView})
                      </Button>
                      <Button
                        className={classes.bulkListBtn}
                        startIcon={<CloseIcon style={{ fontSize: 16 }} />}
                        onClick={() => setPendingDecisions(filtered, 'declined')}
                      >
                        Decline remaining ({pendingInView})
                      </Button>
                    </>
                  )}
                  {decidedInView > 0 && (
                    <Button
                      className={classes.bulkListBtn}
                      onClick={() => clearDecisions(filtered)}
                    >
                      Clear ({decidedInView})
                    </Button>
                  )}
                </Box>
              )}
            </Box>

            <Box className={classes.listPad} role="list" aria-label="Findings by location">
              {groups.map(group => {
                const open = expanded.has(group.key);
                const primaryKind = kindLabel(group.findings[0]?.scope ?? 'task');
                const groupDecisions = group.findings.map(
                  f => decisions.get(violationKey(f)) ?? 'pending',
                );
                const allAccepted = groupDecisions.every(d => d === 'accepted');
                const allDeclined = groupDecisions.every(d => d === 'declined');
                const setGroupDecision = (d: Decision) => {
                  setDecisions(prev => {
                    const next = new Map(prev);
                    group.findings.forEach(f => next.set(violationKey(f), d));
                    return next;
                  });
                };
                return (
                  <Box key={group.key} className={classes.locationCard} role="listitem">
                    <Box
                      className={classes.locationHeader}
                      onClick={() => {
                        setExpanded(prev => {
                          const next = new Set(prev);
                          if (next.has(group.key)) next.delete(group.key);
                          else next.add(group.key);
                          return next;
                        });
                      }}
                    >
                      <span className={classes.locationChevron} aria-hidden>
                        {open ? (
                          <ExpandMoreIcon style={{ fontSize: 16 }} />
                        ) : (
                          <ChevronRightIcon style={{ fontSize: 16 }} />
                        )}
                      </span>
                      <Box className={classes.locationMeta}>
                        <Box className={classes.locationIdentity}>
                          <Typography className={classes.locationTitle} title={group.title}>
                            {group.title}
                          </Typography>
                          <Chip
                            size="small"
                            label={primaryKind}
                            variant="outlined"
                            className={classes.compactLabel}
                          />
                        </Box>
                        <Box className={classes.locationTrailing}>
                          {step === 'ai' &&
                            (() => {
                              const confidences = group.findings
                                .map(f => proposalFor(f, quality.proposals)?.confidence)
                                .filter((c): c is number => typeof c === 'number');
                              if (!confidences.length) return null;
                              const avg =
                                confidences.reduce((a, b) => a + b, 0) / confidences.length;
                              const pct = Math.round(avg * 100);
                              return (
                                <Box
                                  style={{
                                    display: 'inline-flex',
                                    alignItems: 'center',
                                    gap: 6,
                                    marginRight: 8,
                                  }}
                                  onClick={e => e.stopPropagation()}
                                >
                                  <LinearProgress
                                    variant="determinate"
                                    value={pct}
                                    style={{ width: 40, height: 6, borderRadius: 3 }}
                                    color="primary"
                                  />
                                  <Typography
                                    style={{
                                      fontSize: 11,
                                      fontWeight: 600,
                                      color: theme.palette.text.secondary,
                                      minWidth: 28,
                                    }}
                                  >
                                    {pct}%
                                  </Typography>
                                </Box>
                              );
                            })()}
                          {(step === 'quick-fix' || step === 'ai') && (
                            <Box
                              className={classes.decisionGroup}
                              onClick={e => e.stopPropagation()}
                              onKeyDown={e => e.stopPropagation()}
                            >
                              <Button
                                size="small"
                                className={classes.decisionBtn}
                                startIcon={<CheckIcon style={{ fontSize: 14 }} />}
                                onClick={() => setGroupDecision(allAccepted ? 'pending' : 'accepted')}
                                style={{
                                  backgroundColor: allAccepted
                                    ? (isDark ? 'rgba(62,134,53,0.25)' : '#e7f5e7')
                                    : undefined,
                                  color: allAccepted ? '#3E8635' : undefined,
                                }}
                              >
                                Accept
                              </Button>
                              <Button
                                size="small"
                                className={classes.decisionBtn}
                                startIcon={<CloseIcon style={{ fontSize: 14 }} />}
                                onClick={() => setGroupDecision(allDeclined ? 'pending' : 'declined')}
                                style={{
                                  backgroundColor: allDeclined
                                    ? (isDark ? 'rgba(201,25,11,0.2)' : '#fcebeb')
                                    : undefined,
                                  color: allDeclined ? '#C9190B' : undefined,
                                }}
                              >
                                Decline
                              </Button>
                            </Box>
                          )}
                        </Box>
                      </Box>
                    </Box>
                    <Collapse in={open}>
                      {group.findings.map(v => {
                        const key = violationKey(v);
                        const decision = decisions.get(key) ?? 'pending';
                        const proposal = proposalFor(v, quality.proposals);
                        return (
                          <Box key={key} className={classes.findingRow}>
                            <Box className={classes.findingMetaRow}>
                              <Box className={classes.findingMetaLeft}>
                                <Chip
                                  size="small"
                                  label={v.severity}
                                  style={{
                                    height: 20,
                                    fontSize: 10,
                                    fontWeight: 600,
                                    textTransform: 'capitalize',
                                    backgroundColor: `${SEVERITY_COLORS[v.severity]}22`,
                                    color: SEVERITY_COLORS[v.severity],
                                  }}
                                />
                                <Chip
                                  size="small"
                                  label={ruleDisplayCode(v.ruleId)}
                                  title={v.ruleId}
                                  className={classes.ruleBadge}
                                />
                              </Box>
                              <Box className={classes.decisionGroup}>
                                <Button
                                  size="small"
                                  className={classes.decisionBtn}
                                  startIcon={<CheckIcon style={{ fontSize: 14 }} />}
                                  onClick={() => setDecision(key, decision === 'accepted' ? 'pending' : 'accepted')}
                                  style={{
                                    backgroundColor: decision === 'accepted' ? (isDark ? 'rgba(62,134,53,0.25)' : '#e7f5e7') : undefined,
                                    color: decision === 'accepted' ? '#3E8635' : undefined,
                                  }}
                                >
                                  Accept
                                </Button>
                                <Button
                                  size="small"
                                  className={classes.decisionBtn}
                                  startIcon={<CloseIcon style={{ fontSize: 14 }} />}
                                  onClick={() => setDecision(key, decision === 'declined' ? 'pending' : 'declined')}
                                  style={{
                                    backgroundColor: decision === 'declined' ? (isDark ? 'rgba(201,25,11,0.2)' : '#fcebeb') : undefined,
                                    color: decision === 'declined' ? '#C9190B' : undefined,
                                  }}
                                >
                                  Decline
                                </Button>
                              </Box>
                            </Box>
                            <Typography style={{ fontSize: 13 }}>{v.message}</Typography>
                            <Typography
                              style={{
                                fontSize: 11,
                                color: theme.palette.text.secondary,
                                marginTop: 2,
                                fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
                              }}
                            >
                              {v.file}:{v.lineStart}
                            </Typography>
                            {step === 'ai' && typeof proposal?.confidence === 'number' && (
                              <Box
                                style={{
                                  display: 'inline-flex',
                                  alignItems: 'center',
                                  gap: 6,
                                  marginTop: 6,
                                }}
                              >
                                <LinearProgress
                                  variant="determinate"
                                  value={Math.round(proposal.confidence * 100)}
                                  style={{ width: 48, height: 6, borderRadius: 3 }}
                                  color="primary"
                                />
                                <Typography
                                  style={{
                                    fontSize: 11,
                                    fontWeight: 600,
                                    color: theme.palette.text.secondary,
                                  }}
                                >
                                  {Math.round(proposal.confidence * 100)}% confidence
                                </Typography>
                              </Box>
                            )}
                            {proposal ? (
                              <ProposalDiff proposal={proposal} classes={classes} isDark={isDark} />
                            ) : (
                              <Typography
                                style={{
                                  fontSize: 12,
                                  color: theme.palette.text.secondary,
                                  marginTop: 8,
                                  fontStyle: 'italic',
                                }}
                              >
                                No proposed diff available for this finding.
                              </Typography>
                            )}
                          </Box>
                        );
                      })}
                    </Collapse>
                  </Box>
                );
              })}
            </Box>
          </Box>
        )}

        {/* Post-PR: keep green stepper, show Assess outcome (same panel as Quality tab). */}
        {step === 'commit' && pushed && finishResult && (
          <Box style={{ marginTop: 8 }}>
            <QualityFindingsPanel
              quality={quality}
              remediationResult={finishResult}
              onScan={() => finishToQuality()}
              onViewHistory={() => finishToQuality()}
              onRemediate={() => finishToQuality({ reopenRemediate: true })}
            />
          </Box>
        )}

        {step === 'commit' && !pushed && (
          <Box
            style={{
              padding: 20,
              borderRadius: 8,
              border: `1px solid ${theme.palette.divider}`,
              backgroundColor: theme.palette.background.paper,
            }}
          >
            <Typography style={{ fontSize: 16, fontWeight: 600, marginBottom: 4 }}>
              {totalAccepted > 0
                ? `Push ${totalAccepted} accepted fix${totalAccepted === 1 ? '' : 'es'}`
                : 'Push accepted fixes'}
            </Typography>
            <Typography style={{ fontSize: 13, color: theme.palette.text.secondary, marginBottom: 16 }}>
              Create a branch, push the fixes, and optionally open a pull request.
            </Typography>

            <Box style={{ display: 'flex', gap: 24, marginBottom: 20, flexWrap: 'wrap' }}>
              <Box>
                <Typography style={{ fontSize: 24, fontWeight: 700 }}>{acceptedCount(quickFixItems)}</Typography>
                <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>Quick-fix accepted</Typography>
              </Box>
              <Box>
                <Typography style={{ fontSize: 24, fontWeight: 700 }}>{acceptedCount(aiItems)}</Typography>
                <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>AI accepted</Typography>
              </Box>
              <Box>
                <Typography style={{ fontSize: 24, fontWeight: 700 }}>{manualItems.length}</Typography>
                <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>Manual (not included)</Typography>
              </Box>
            </Box>

            {totalAccepted === 0 ? (
              <Typography style={{ fontSize: 13, color: theme.palette.text.secondary }}>
                Nothing accepted yet. Go back to accept fixes, or return to Quality without pushing.
              </Typography>
            ) : (
              <Box style={{ maxWidth: 420 }}>
                <TextField
                  id="remediation-branch-name"
                  label="Branch name"
                  value={branchName}
                  onChange={e => setBranchName(e.target.value)}
                  variant="outlined"
                  size="small"
                  fullWidth
                  helperText="APME pushes accepted fixes to this branch."
                />
                <FormControlLabel
                  style={{ marginTop: 12, marginLeft: 0, alignItems: 'flex-start' }}
                  control={
                    <Checkbox
                      color="primary"
                      checked={openPullRequest}
                      onChange={e => setOpenPullRequest(e.target.checked)}
                      style={{ paddingTop: 2 }}
                    />
                  }
                  label={
                    <Box>
                      <Typography style={{ fontSize: 14 }}>Open a pull request after push</Typography>
                      <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>
                        Recommended so reviewers can approve the changes in your SCM.
                      </Typography>
                    </Box>
                  }
                />
              </Box>
            )}
          </Box>
        )}

        {!pushed && (showNext || showSkip || showPushAction) && (
          <Box className={classes.footer}>
            <Typography className={classes.footerHint}>{footerHint}</Typography>
            {actionButtons}
          </Box>
        )}

        <Dialog
          open={aiConfirmOpen}
          onClose={() => setAiConfirmOpen(false)}
          aria-labelledby="ai-confirm-title"
          maxWidth="xs"
          fullWidth
        >
          <DialogTitle id="ai-confirm-title">Generate AI suggestions?</DialogTitle>
          <DialogContent>
            <DialogContentText style={{ fontSize: 14, color: theme.palette.text.primary }}>
              {acceptedAiCount === 1
                ? 'Generate an AI suggestion for 1 accepted finding. This uses AI tokens.'
                : `Generate AI suggestions for ${acceptedAiCount} accepted findings. This uses AI tokens.`}
            </DialogContentText>
          </DialogContent>
          <DialogActions style={{ padding: '8px 24px 16px' }}>
            <Button
              onClick={() => setAiConfirmOpen(false)}
              style={{ textTransform: 'none', borderRadius: 20 }}
            >
              Cancel
            </Button>
            <Button
              variant="contained"
              color="primary"
              onClick={confirmAiAndContinue}
              style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500 }}
            >
              Generate with AI
            </Button>
          </DialogActions>
        </Dialog>
    </Box>
  );
};
