/**
 * Deep-link shim → Quality tab remediation drilldown.
 * Prefer in-tab entry from Quality; this keeps old /quality/remediate URLs working.
 */
import { Navigate, useParams, useSearchParams } from 'react-router-dom';
import { useRouteRef } from '@backstage/core-plugin-api';
import { rootRouteRef } from '../../routes';

export { RemediationWorkspace } from './RemediationWorkspace';

export const RemediationWorkspacePage = () => {
  const { repositoryName = '' } = useParams<{ repositoryName: string }>();
  const [searchParams] = useSearchParams();
  const rootLink = useRouteRef(rootRouteRef);
  const resume = searchParams.get('resume') === '1';
  const params = new URLSearchParams({ tab: 'quality' });
  if (resume) params.set('resume', '1');
  else params.set('remediate', '1');
  return (
    <Navigate
      to={`${rootLink()}/repositories/${repositoryName}?${params.toString()}`}
      replace
    />
  );
};
