export interface ViolationDetailModalProps {
  open: boolean;
  onClose: () => void;
  title: string;
  subtitle?: string;
  violations: QualityViolation[];
  totalProjectViolations?: number;
  fixableCount?: number;
  projectName?: string;
  onNavigateToQuality?: (category?: string, rule?: string) => void;
  repoUrl?: string;
  branch?: string;
  lastScannedAt?: string;
  lastScannedCommit?: string;
}

export function ViolationDetailModal({
  open,
  onClose,
  title,
  subtitle,
  violations,
  totalProjectViolations,
  fixableCount,
  projectName,
  onNavigateToQuality,
  repoUrl,
  branch,
  lastScannedAt,
  lastScannedCommit,
}: ViolationDetailModalProps) {
  const classes = useStyles();
  const theme = useTheme();
  const [acknowledgedIds, setAcknowledgedIds] = useState<Set<string>>(new Set());

  const toggleAcknowledge = (key: string) => {
    setAcknowledgedIds(prev => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  const getKey = (v: QualityViolation, i: number) => `${v.ruleId}:${v.file}:${v.lineStart}:${i}`;

  const sevOrder: SeverityClass[] = ['critical', 'high', 'medium', 'low', 'info'];
  const sorted = useMemo(() =>
    [...violations].sort((a, b) => sevOrder.indexOf(a.severity) - sevOrder.indexOf(b.severity)),
    [violations],
  );

  const severitySummary = useMemo(() => {
    const counts: Partial<Record<SeverityClass, number>> = {};
    for (const v of violations) {
      counts[v.severity] = (counts[v.severity] ?? 0) + 1;
    }
    return sevOrder.filter(s => (counts[s] ?? 0) > 0).map(s => ({ severity: s, count: counts[s]! }));
  }, [violations]);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth={false}
      PaperProps={{ className: classes.dialogPaper }}
    >
      {/* Header */}
      <Box className={classes.header}>
        <Box style={{ minWidth: 0 }}>
          <Typography style={{ fontSize: 16, fontWeight: 600, marginBottom: 2 }}>
            {title}
          </Typography>
          <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>
            {projectName && <><GitHubIcon style={{ fontSize: 11, verticalAlign: 'middle', marginRight: 3, opacity: 0.6 }} />{projectName} · </>}
            {subtitle && <>{subtitle} · </>}
            {lastScannedAt ? <>Scanned {lastScannedAt}{lastScannedCommit ? ` (${lastScannedCommit})` : ''}</> : null}
          </Typography>
        </Box>
        <IconButton size="small" onClick={onClose} style={{ marginTop: -4 }}>
          <CloseIcon style={{ fontSize: 18 }} />
        </IconButton>
      </Box>

      {/* Violation rows */}
      <Box className={classes.body}>
        {sorted.map((v, i) => {
          const key = getKey(v, i);
          const isAcknowledged = acknowledgedIds.has(key);
          const sevStyle = FILLED_SEVERITY[v.severity] || FILLED_SEVERITY.info;

          return (
            <Box key={key} className={`${classes.violationRow} ${isAcknowledged ? classes.acknowledgedRow : ''}`}>
              <Box display="flex" alignItems="center" style={{ gap: 10, marginBottom: 6 }}>
                <span className={classes.severityChip} style={{ backgroundColor: sevStyle.bg, color: sevStyle.color }}>
                  {v.severity}
                </span>
                <span className={classes.message}>{v.message}</span>
              </Box>

              <Typography className={classes.detailDescription}>
                {(() => {
                  const fixIdx = v.ruleDescription?.indexOf('Fixed in');
                  if (fixIdx != null && fixIdx > 0) {
                    return <>{v.ruleDescription.slice(0, fixIdx)}<strong style={{ fontWeight: 600 }}>{v.ruleDescription.slice(fixIdx)}</strong></>;
                  }
                  return v.ruleDescription;
                })()}
              </Typography>

              {DEMO_CODE_CONTEXT[v.ruleId] && (
                <Box className={classes.codeBlock}>
                  {DEMO_CODE_CONTEXT[v.ruleId].lines.map((line, li) => (
                    <Box
                      key={li}
                      className={`${classes.codeLine} ${line.highlighted ? classes.codeLineHighlighted : ''}`}
                    >
                      <span className={classes.codeLineNum}>{line.num}</span>
                      <span className={classes.codeLineText}>{line.text}</span>
                    </Box>
                  ))}
                </Box>
              )}

              <Box display="flex" alignItems="center" justifyContent="space-between" style={{ gap: 8 }}>
                <span className={classes.detailMetaItem}>
                  <a
                    className={classes.fileLink}
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      if (repoUrl) window.open(`${repoUrl}/blob/${branch ?? 'main'}/${v.file}#L${v.lineStart}`, '_blank');
                    }}
                  >
                    <GitHubIcon style={{ fontSize: 11, marginRight: 4, verticalAlign: 'middle', opacity: 0.7 }} />
                    {v.file}:{v.lineStart}
                  </a>
                </span>
                <Box display="flex" alignItems="center" style={{ gap: 6, flexShrink: 0 }}>
                  <Tooltip title={isAcknowledged
                    ? 'Click to undo — this finding will appear again in future scans'
                    : 'Mark as reviewed and accepted — this finding won\'t appear again unless the underlying code changes'
                  } arrow enterDelay={300}>
                    <Button
                      variant="outlined"
                      size="small"
                      color={isAcknowledged ? undefined : 'primary'}
                      className={isAcknowledged ? classes.acknowledgeBtnActive : undefined}
                      startIcon={isAcknowledged ? <CheckCircleOutlineIcon style={{ fontSize: 13 }} /> : undefined}
                      onClick={(e) => { e.stopPropagation(); toggleAcknowledge(key); }}
                      style={{ textTransform: 'none', fontSize: 11, padding: '3px 12px', minWidth: 0, borderRadius: 20 }}
                    >
                      {isAcknowledged ? 'Acknowledged' : 'Acknowledge'}
                    </Button>
                  </Tooltip>
                  <Button
                    size="small"
                    variant="outlined"
                    startIcon={<CodeIcon style={{ fontSize: 13 }} />}
                    onClick={(e) => {
                      e.stopPropagation();
                      window.open(`/devspaces-mockup.html?state=edit&file=${encodeURIComponent(v.file)}&line=${v.lineStart}&rule=${encodeURIComponent(v.ruleId)}`, '_blank');
                    }}
                    className={classes.acknowledgeBtn}
                  >
                    Edit in Dev Spaces
                  </Button>
                </Box>
              </Box>
            </Box>
          );
        })}
      </Box>

      {/* Footer */}
      <Box className={classes.footer}>
        <Typography style={{ fontSize: 12, color: theme.palette.text.secondary }}>
          Found in latest quality scan
          {totalProjectViolations != null && totalProjectViolations > violations.length && (
            <> · {totalProjectViolations - violations.length} other violation{totalProjectViolations - violations.length !== 1 ? 's' : ''} in this repository</>
          )}
          {acknowledgedIds.size > 0 && ` · ${acknowledgedIds.size} acknowledged`}
        </Typography>
        {onNavigateToQuality && totalProjectViolations != null && totalProjectViolations > violations.length && (
          <Typography
            onClick={() => {
              onClose();
              onNavigateToQuality(undefined);
            }}
            style={{ fontSize: 12, fontWeight: 500, color: theme.palette.primary.main, cursor: 'pointer', flexShrink: 0 }}
          >
            View in Quality tab →
          </Typography>
        )}
      </Box>
    </Dialog>
  );
}
