// ---------------------------------------------------------------------------
// FixChipStyled
// ---------------------------------------------------------------------------
const FixChipStyled = ({
  mode,
  method,
  status,
  pageState,
  classes,
}: {
  mode: 'tier' | 'status';
  method: 'deterministic' | 'ai' | 'manual';
  status: UnifiedViolationStatus;
  pageState?: QualityPageState;
  category?: ViolationCategory;
  classes: ReturnType<typeof useQualityStyles>;
}) => {
  // Suggestion exists only after scan (auto) or generate (AI) — not merely because we're on the results page
  const hasSuggestion = status === 'proposed' || status === 'declined' || status === 'in-pr' || status === 'resolved';

  if (mode === 'tier') {
    const label = method === 'deterministic'
      ? (hasSuggestion ? 'Auto-fix' : 'Auto-fixable')
      : method === 'ai'
        ? 'AI'
        : 'Manual';
    const chipClass =
      method === 'deterministic' ? classes.fixChipDeterministic
        : method === 'ai'
          ? (hasSuggestion ? classes.fixChipAi : classes.fixChipAiPending)
          : classes.fixChipManual;
    const tooltip = method === 'deterministic' && hasSuggestion
      ? 'Auto-fix — ready from the scan. Does not use AI.'
      : method === 'ai' && hasSuggestion
        ? 'AI — suggestion ready. Review before including in a pull request.'
        : method === 'ai'
          ? 'AI — no suggestion yet. Generate when you choose (may incur usage costs). Classification from the scan does not use AI.'
          : TIER_TOOLTIPS[method];

    return (
      <DarkTooltip title={tooltip} arrow enterDelay={200}>
        <span className={`${classes.fixChip} ${chipClass}`}>
          <span className={classes.fixChipIcon} style={{ display: 'inline-flex', alignItems: 'center' }}>
            {method === 'ai' && hasSuggestion
              ? <CheckIcon style={{ fontSize: 12 }} />
              : method === 'deterministic' ? '⚡' : method === 'ai' ? '✦' : '—'}
          </span>
          {label}
        </span>
      </DarkTooltip>
    );
  }

  let label = 'Manual';
  let chipClass = classes.fixChipManual;
  let tooltip = TIER_TOOLTIPS.manual;
  let iconNode: ReactNode = null;

  if (status === 'proposed') {
    label = method === 'ai' ? 'AI' : method === 'deterministic' ? 'Auto-fix' : 'Proposed';
    chipClass = method === 'ai' ? classes.fixChipAi : method === 'deterministic' ? classes.fixChipDeterministic : classes.fixChipReview;
    tooltip = method === 'ai'
      ? 'AI — suggestion ready. Select to include in the pull request.'
      : 'Auto-fix ready — select to include in the pull request';
    iconNode = method === 'ai'
      ? <CheckIcon style={{ fontSize: 12 }} />
      : method === 'deterministic' ? '⚡' : null;
  } else if (status === 'in-pr') {
    label = 'In PR'; chipClass = classes.fixChipInPr;
    tooltip = 'Included in the open pull request';
  } else if (status === 'resolved') {
    label = 'Resolved'; chipClass = classes.fixChipApplied;
    tooltip = 'Resolved — change was merged and the violation is addressed';
    iconNode = '✓';
  } else if (status === 'declined' || status === 'open') {
    // Post-PR outcome mode: anything not in this PR
    label = 'Not in PR'; chipClass = classes.fixChipDeclined;
    tooltip = 'Not included in this pull request. Scan again to remediate in a new batch.';
  } else if (method !== 'manual') {
    label = method === 'deterministic' ? 'Auto-fixable' : 'AI';
    chipClass = method === 'deterministic' ? classes.fixChipDeterministic : classes.fixChipAiPending;
    tooltip = TIER_TOOLTIPS[method];
    iconNode = method === 'deterministic' ? '⚡' : '✦';
  }

  return (
    <DarkTooltip title={tooltip} arrow enterDelay={200}>
      <span className={`${classes.fixChip} ${chipClass}`}>
        {iconNode != null && (
          <span className={classes.fixChipIcon} style={{ display: 'inline-flex', alignItems: 'center' }}>
            {iconNode}
          </span>
        )}
        {label}
      </span>
    </DarkTooltip>
  );
};

