/** Assess views: location (content path), file, or flat (one row per finding). */
type ViewMode = 'by-location' | 'by-file' | 'flat';
type FixType = 'quick-fix' | 'ai' | 'manual';
/** Post-remediation list filter. Remaining = not in PR (declined is a row status). */
