const KIND_LABELS: Record<string, string> = {
  task: 'Task',
  play: 'Play',
  role: 'Role',
  playbook: 'Playbook',
  collection: 'Collection',
  block: 'Block',
  inventory: 'Inventory',
};

function violationKey(v: QualityViolation): string {
  return `${v.ruleId}:${v.file}:${v.lineStart}`;
}

function fixTypeOf(v: QualityViolation): FixType {
  if (v.fixTier === 'deterministic') return 'quick-fix';
  if (v.fixTier === 'ai') return 'ai';
  return 'manual';
}

/** Content location path (SPA `path` / yamlPath); path-less findings share one bucket. */
function locationGroupKey(v: QualityViolation): string {
  const path = (v.yamlPath || '').trim();
  if (path) return path;
  return '__no-location__';
}

function locationTitle(v: QualityViolation): string {
  const path = (v.yamlPath || '').trim();
  if (path) return path;
  if (v.file) {
    return v.lineStart > 0 ? `${v.file}:${v.lineStart}` : v.file;
  }
  return 'Not tied to a location';
}

function fileKey(v: QualityViolation): string {
  return (v.file || '').trim() || 'Not tied to a file';
}

function kindLabel(scope: string): string {
  return KIND_LABELS[scope] ?? scope.charAt(0).toUpperCase() + scope.slice(1);
}

function primaryKind(findings: QualityViolation[]): string {
  const counts = new Map<string, number>();
  findings.forEach(v => counts.set(v.scope, (counts.get(v.scope) ?? 0) + 1));
  let best = findings[0]?.scope ?? 'task';
  let bestN = 0;
  counts.forEach((n, scope) => {
    if (n > bestN) {
      best = scope;
      bestN = n;
    }
  });
  return best;
}

function severityBreakdown(
  findings: QualityViolation[],
): { sev: SeverityClass; count: number }[] {
  return SEVERITY_ORDER.map(sev => ({
    sev,
    count: findings.filter(f => f.severity === sev).length,
  })).filter(x => x.count > 0);
}

function sortFindings(items: QualityViolation[]): QualityViolation[] {
  return [...items].sort(
    (a, b) => SEVERITY_ORDER.indexOf(a.severity) - SEVERITY_ORDER.indexOf(b.severity),
  );
}

function groupFindings(findings: QualityViolation[], mode: ViewMode): FindingGroup[] {
  if (mode === 'flat') {
    return sortFindings(findings).map(v => ({
      key: `flat:${violationKey(v)}`,
      title: locationTitle(v),
      findings: [v],
    }));
  }

  const byKey = new Map<string, QualityViolation[]>();
  const keyOf = mode === 'by-file' ? fileKey : locationGroupKey;
  findings.forEach(v => {
    const key = keyOf(v);
    const list = byKey.get(key) ?? [];
    list.push(v);
    byKey.set(key, list);
  });

  return [...byKey.entries()]
    .sort(([a], [b]) => {
      if (a === '__no-location__') return 1;
      if (b === '__no-location__') return -1;
      return a.localeCompare(b);
    })
    .map(([key, items]) => ({
      key,
      title: key === '__no-location__' ? 'Not tied to a location' : key,
      findings: sortFindings(items),
    }));
}

function bestCurrentLines(
  findings: QualityViolation[],
  proposals: ProjectQualityData['proposals'],
): string[] {
  let best: string[] = [];
  findings.forEach(v => {
    const lines = currentSnippetFor(v, proposals);
    if (lines.length > best.length) best = lines;
  });
  return best;
}

function uniqueLocationCount(items: QualityViolation[]): number {
  const paths = new Set<string>();
  items.forEach(v => paths.add(locationGroupKey(v)));
  return paths.size;
}

function toggleInSet<T>(prev: Set<T>, value: T): Set<T> {
  const next = new Set(prev);
  if (next.has(value)) {
    if (next.size <= 1) return prev;
    next.delete(value);
  } else {
    next.add(value);
  }
  return next;
}

