export type QualityFindingsPanelProps = {
  quality: ProjectQualityData;
  scanning?: boolean;
  scanProgress?: number;
  initialSeverity?: SeverityClass | null;
  /** Durable outcome after push/PR from remediation drilldown (tab session). */
  remediationResult?: RemediationFinishResult | null;
  /** True after the user entered remediation without finishing (push/PR). */
  sessionInProgress?: boolean;
  onScan: () => void;
  onViewHistory: () => void;
  onRemediate?: () => void;
  onResume?: () => void;
};

export function QualityFindingsPanel({
  quality,
  scanning = false,
  scanProgress = 0,
  initialSeverity,
  remediationResult = null,
  sessionInProgress = false,
  onScan,
  onViewHistory,
  onRemediate,
  onResume,
}: QualityFindingsPanelProps) {
  const classes = useStyles();
  const theme = useTheme();
  const isDark = theme.palette.type === 'dark';

  const [viewMode, setViewMode] = useState<ViewMode>('by-location');
  const [severityFilters, setSeverityFilters] = useState<Set<SeverityClass>>(() => {
    if (initialSeverity) return new Set([initialSeverity]);
    return new Set(SEVERITY_ORDER.filter(s => (quality.severityBreakdown[s] ?? 0) > 0));
  });
  const [fixFilters, setFixFilters] = useState<Set<FixType>>(() => new Set(FIX_ORDER));
  const [kindFilters, setKindFilters] = useState<Set<string>>(() => {
    const kinds = new Set(quality.violations.map(v => v.scope));
    return kinds;
  });
  /** Expanded location/file/flat rows (one drawer per group). */
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(() => new Set());
  /** Sticky selection — click a finding to pin highlight in Current. */
  const [selectedKey, setSelectedKey] = useState<string | null>(null);
  /** Ephemeral highlight — hover short rule id (Brad). */
  const [hoverKey, setHoverKey] = useState<string | null>(null);
  const [viewMenuEl, setViewMenuEl] = useState<HTMLElement | null>(null);
  const [fixMenuEl, setFixMenuEl] = useState<HTMLElement | null>(null);
  const [kindMenuEl, setKindMenuEl] = useState<HTMLElement | null>(null);
  const [outcomeFilter, setOutcomeFilter] = useState<OutcomeFilter>('all');
  /** Idle: View / Fix type / Kind tucked until asked. Post-PR: always available. */
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);
  const activeKey = hoverKey ?? selectedKey;
  const previewLineRefs = useRef<Map<string, HTMLElement>>(new Map());

  const violations = quality.violations;
  const scan = quality.latestScan;
  const inPrKeys = useMemo(
    () => new Set(remediationResult?.acceptedKeys ?? []),
    [remediationResult],
  );
  const declinedKeys = useMemo(
    () => new Set(remediationResult?.declinedKeys ?? []),
    [remediationResult],
  );
  const inPrCount = inPrKeys.size;
  /** Findings not in the PR / push — still open against the scan. Includes declined. */
  const remainingCount = Math.max(0, violations.length - inPrCount);

  const matchesOutcome = (key: string, filter: OutcomeFilter): boolean => {
    if (filter === 'all') return true;
    if (filter === 'accepted') return inPrKeys.has(key);
    // Remaining = everything not accepted into the PR / push (includes declined)
    return !inPrKeys.has(key);
  };
  // Resume only when a remediation session was started and not finished (push/PR).
  const showResume =
    (sessionInProgress || Boolean(quality.liveSessionAvailable)) &&
    !remediationResult &&
    Boolean(onResume);
  // Idle start — same banner chrome as Resume; header keeps only post-PR "Remediate remaining".
  const showStartRemediate =
    violations.length > 0 &&
    !scanning &&
    !showResume &&
    !remediationResult &&
    Boolean(onRemediate);
  const hasOpenPr = Boolean(remediationResult?.prUrl);

  const presentSeverities = useMemo(
    () => SEVERITY_ORDER.filter(s => violations.some(v => v.severity === s)),
    [violations],
  );
  const presentFixTypes = useMemo(() => {
    const counts: Record<FixType, number> = { 'quick-fix': 0, ai: 0, manual: 0 };
    violations.forEach(v => { counts[fixTypeOf(v)] += 1; });
    return FIX_ORDER.filter(f => counts[f] > 0).map(f => ({ type: f, count: counts[f] }));
  }, [violations]);
  const presentKinds = useMemo(() => {
    const counts = new Map<string, number>();
    violations.forEach(v => counts.set(v.scope, (counts.get(v.scope) ?? 0) + 1));
    return [...counts.entries()]
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([scope, count]) => ({ scope, count }));
  }, [violations]);

  /** Findings matching Fix type + Kind. */
  const facetByFixKind = useMemo(() => {
    return violations.filter(v => {
      if (fixFilters.size > 0 && !fixFilters.has(fixTypeOf(v))) return false;
      if (kindFilters.size > 0 && !kindFilters.has(v.scope)) return false;
      return true;
    });
  }, [violations, fixFilters, kindFilters]);

  /** Outcome tab scopes the severity bar, chips, and list. */
  const facetByOutcome = useMemo(() => {
    if (!remediationResult || outcomeFilter === 'all') return facetByFixKind;
    return facetByFixKind.filter(v => matchesOutcome(violationKey(v), outcomeFilter));
    // matchesOutcome reads inPr/declined sets
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [facetByFixKind, remediationResult, outcomeFilter, inPrKeys, declinedKeys]);

  const severityFacetCounts = useMemo(() => {
    const counts = Object.fromEntries(SEVERITY_ORDER.map(s => [s, 0])) as Record<
      SeverityClass,
      number
    >;
    facetByOutcome.forEach(v => {
      counts[v.severity] += 1;
    });
    return counts;
  }, [facetByOutcome]);

  const severityFacetOrder = useMemo(
    () => SEVERITY_ORDER.filter(s => severityFacetCounts[s] > 0),
    [severityFacetCounts],
  );

  const severityFacetTotal = useMemo(
    () => severityFacetOrder.reduce((sum, s) => sum + severityFacetCounts[s], 0),
    [severityFacetOrder, severityFacetCounts],
  );

  const filtered = useMemo(() => {
    return facetByOutcome.filter(v => {
      if (severityFilters.size > 0 && !severityFilters.has(v.severity)) return false;
      return true;
    });
  }, [facetByOutcome, severityFilters]);

  const groups = useMemo(
    () => groupFindings(filtered, viewMode),
    [filtered, viewMode],
  );

  /** Assess, post-PR, and filter changes: drawers open by default. */
  const groupKeySig = useMemo(() => groups.map(g => g.key).join('\0'), [groups]);
  useEffect(() => {
    setExpandedGroups(new Set(groups.map(g => g.key)));
  }, [groupKeySig]); // eslint-disable-line react-hooks/exhaustive-deps

  const inventory = useMemo(() => {
    const buckets: Record<FixType | 'total', QualityViolation[]> = {
      total: violations,
      'quick-fix': [],
      ai: [],
      manual: [],
    };
    violations.forEach(v => buckets[fixTypeOf(v)].push(v));
    return [
      {
        key: 'total',
        label: 'Findings',
        primary: buckets.total.length,
        secondary: uniqueLocationCount(buckets.total),
        tone: theme.palette.text.primary,
      },
      {
        key: 'quick-fix',
        label: 'Quick-fix',
        primary: buckets['quick-fix'].length,
        secondary: uniqueLocationCount(buckets['quick-fix']),
        tone: isDark ? '#8bc986' : '#3E8635',
      },
      {
        key: 'ai',
        label: 'AI-eligible fix',
        primary: buckets.ai.length,
        secondary: uniqueLocationCount(buckets.ai),
        tone: isDark ? '#c4b5e3' : '#6753ac',
      },
      {
        key: 'manual',
        label: 'Manual fix',
        primary: buckets.manual.length,
        secondary: uniqueLocationCount(buckets.manual),
        tone: theme.palette.text.primary,
      },
    ];
  }, [violations, theme, isDark]);

  const selectFinding = (key: string, opts?: { scrollPreview?: boolean }) => {
    setSelectedKey(key);
    if (opts?.scrollPreview === false) return;
    requestAnimationFrame(() => {
      previewLineRefs.current.get(key)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    });
  };

  const expandAll = () => {
    setExpandedGroups(new Set(groups.map(g => g.key)));
    const top = groups[0]?.findings[0];
    if (top) selectFinding(violationKey(top), { scrollPreview: false });
  };

  const collapseAll = () => {
    setExpandedGroups(new Set());
    setSelectedKey(null);
    setHoverKey(null);
  };

  const toggleGroup = (key: string) => {
    setExpandedGroups(prev => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
        const group = groups.find(g => g.key === key);
        const top = group?.findings[0];
        if (top) {
          const vKey = violationKey(top);
          setSelectedKey(vKey);
          requestAnimationFrame(() => {
            previewLineRefs.current.get(vKey)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          });
        }
      }
      return next;
    });
  };

  const presentSeveritiesInScope = useMemo(
    () => SEVERITY_ORDER.filter(s => facetByOutcome.some(v => v.severity === s)),
    [facetByOutcome],
  );
  const severityNarrowed = presentSeveritiesInScope.some(s => !severityFilters.has(s));
  const fixNarrowed = presentFixTypes.some(f => !fixFilters.has(f.type));
  const kindNarrowed = presentKinds.some(k => !kindFilters.has(k.scope));
  const filtersActive = severityNarrowed || fixNarrowed || kindNarrowed;

  const selectOutcomeFilter = (value: OutcomeFilter) => {
    setOutcomeFilter(value);
    const scoped =
      !remediationResult || value === 'all'
        ? facetByFixKind
        : facetByFixKind.filter(v => matchesOutcome(violationKey(v), value));
    const present = SEVERITY_ORDER.filter(s => scoped.some(v => v.severity === s));
    setSeverityFilters(new Set(present.length ? present : presentSeverities));
  };
  const viewLabel = VIEW_OPTIONS.find(o => o.id === viewMode)?.label ?? 'View';
  const fixSelectedCount = presentFixTypes.filter(f => fixFilters.has(f.type)).length;
  const kindSelectedCount = presentKinds.filter(k => kindFilters.has(k.scope)).length;
  const exclusiveFixType =
    fixSelectedCount === 1
      ? presentFixTypes.find(f => fixFilters.has(f.type))?.type ?? null
      : null;

  const clearFixTypeFilter = () => {
    setFixFilters(new Set(presentFixTypes.map(f => f.type)));
  };

  const applyInventoryFixFilter = (key: 'total' | FixType) => {
    if (key === 'total') {
      clearFixTypeFilter();
      return;
    }
    // Re-click active bucket → show all (click out)
    if (exclusiveFixType === key) {
      clearFixTypeFilter();
      return;
    }
    setFixFilters(new Set([key]));
  };

  const clearAllFilters = () => {
    setSeverityFilters(new Set(presentSeveritiesInScope));
    clearFixTypeFilter();
    setKindFilters(new Set(presentKinds.map(k => k.scope)));
  };

  const severityChip = (sev: SeverityClass, selected: boolean) => {
    const count = severityFacetCounts[sev];
    return (
      <Tooltip
        key={sev}
        title={`${SEVERITY_TOOLTIPS[sev]} (${count})`}
        arrow
        enterDelay={250}
      >
        <Box component="span" style={{ display: 'inline-flex' }}>
          <Chip
            size="small"
            label={`${sev.charAt(0).toUpperCase() + sev.slice(1)} (${count})`}
            className={classes.pill}
            onClick={() => setSeverityFilters(prev => toggleInSet(prev, sev))}
            variant="outlined"
            style={{
              backgroundColor: selected ? `${SEVERITY_COLORS[sev]}22` : 'transparent',
              color: selected ? SEVERITY_COLORS[sev] : theme.palette.text.secondary,
              border: `1px solid ${selected ? `${SEVERITY_COLORS[sev]}88` : theme.palette.divider}`,
              opacity: selected ? 1 : 0.45,
            }}
          />
        </Box>
      </Tooltip>
    );
  };

  const renderOutcomeDiff = (
    v: QualityViolation,
    mode: 'accepted' | 'declined',
  ) => {
    const proposal = proposalFor(v, quality.proposals);
    if (!proposal) {
      return (
        <Typography
          style={{
            fontSize: 12,
            color: theme.palette.text.secondary,
            marginTop: 8,
            fontStyle: 'italic',
          }}
        >
          {mode === 'accepted'
            ? 'Fix accepted — no diff preview available.'
            : 'Fix declined — no preview of the declined change available.'}
        </Typography>
      );
    }
    const removedBg = isDark ? 'rgba(201,25,11,0.18)' : '#fcebeb';
    const addedBg =
      mode === 'accepted'
        ? isDark
          ? 'rgba(62,134,53,0.18)'
          : '#e7f5e7'
        : isDark
          ? 'rgba(201,25,11,0.12)'
          : '#f5f0f0';
    const afterTitle =
      mode === 'accepted' ? 'After (in pull request)' : 'Declined fix (not applied)';
    return (
      <Box className={classes.outcomeDiff}>
        {proposal.explanation ? (
          <Typography className={classes.outcomeDiffExplainer}>
            {proposal.explanation}
          </Typography>
        ) : null}
        <Box className={classes.outcomeDiffGrid}>
          <Box>
            <Typography className={classes.outcomeDiffPaneTitle}>Before</Typography>
            {(proposal.current.length ? proposal.current : ['(no lines)']).map((line, i) => (
              <Typography
                key={`b-${i}`}
                className={classes.outcomeDiffLine}
                style={{ backgroundColor: removedBg }}
              >
                {line || ' '}
              </Typography>
            ))}
          </Box>
          <Box style={{ borderLeft: `1px solid ${theme.palette.divider}` }}>
            <Typography className={classes.outcomeDiffPaneTitle}>{afterTitle}</Typography>
            {(proposal.proposed.length ? proposal.proposed : ['(removed)']).map((line, i) => (
              <Typography
                key={`a-${i}`}
                className={classes.outcomeDiffLine}
                style={{ backgroundColor: addedBg }}
              >
                {line || ' '}
              </Typography>
            ))}
          </Box>
        </Box>
      </Box>
    );
  };

  const renderFindingSubRow = (v: QualityViolation) => {
    const key = violationKey(v);
    const fix = fixTypeOf(v);
    const inPr = inPrKeys.has(key);
    const declined = declinedKeys.has(key);
    const selected = selectedKey === key;
    return (
      <Box
        key={key}
        role="listitem"
        aria-selected={selected}
        className={`${classes.findingSubRow}${selected ? ` ${classes.findingSubRowSelected}` : ''}`}
        onClick={() => selectFinding(key)}
        onKeyDown={e => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            selectFinding(key);
          }
        }}
        tabIndex={0}
      >
        <Box className={classes.findingSubMeta}>
          <Tooltip
            arrow
            enterDelay={450}
            title={
              <Box style={{ padding: '2px 0', maxWidth: 320 }}>
                {ruleDisplayCode(v.ruleId) !== v.ruleId && (
                  <Typography
                    style={{
                      fontSize: 12,
                      fontWeight: 600,
                      fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
                      marginBottom: 4,
                    }}
                  >
                    {v.ruleId}
                  </Typography>
                )}
                <Typography style={{ fontSize: 12, lineHeight: 1.45 }}>
                  {v.ruleDescription}
                </Typography>
              </Box>
            }
          >
            <Box
              component="span"
              className={classes.findingRuleId}
              tabIndex={0}
              aria-label={`Rule ${ruleDisplayCode(v.ruleId)}: ${v.ruleId}. Hover to highlight in Current.`}
              onMouseEnter={() => setHoverKey(key)}
              onMouseLeave={() => setHoverKey(prev => (prev === key ? null : prev))}
              onFocus={() => setHoverKey(key)}
              onBlur={() => setHoverKey(prev => (prev === key ? null : prev))}
              onClick={e => {
                e.stopPropagation();
                selectFinding(key);
              }}
            >
              {ruleDisplayCode(v.ruleId)}
            </Box>
          </Tooltip>
          <Chip
            size="small"
            label={v.severity.charAt(0).toUpperCase() + v.severity.slice(1)}
            className={classes.compactLabel}
            style={{
              backgroundColor: `${SEVERITY_COLORS[v.severity]}22`,
              color: SEVERITY_COLORS[v.severity],
              border: `1px solid ${SEVERITY_COLORS[v.severity]}55`,
            }}
          />
          {remediationResult ? (
            (() => {
              const label = inPr ? 'Fix accepted' : declined ? 'Fix declined' : 'Remaining';
              const tone = inPr
                ? { bg: isDark ? 'rgba(62,134,53,0.2)' : 'rgba(62,134,53,0.12)', fg: '#3E8635', bd: 'rgba(62,134,53,0.45)' }
                : declined
                  ? { bg: isDark ? 'rgba(201,25,11,0.15)' : 'rgba(201,25,11,0.08)', fg: '#C9190B', bd: 'rgba(201,25,11,0.35)' }
                  : { bg: 'transparent', fg: theme.palette.text.secondary, bd: theme.palette.divider };
              return (
                <Chip
                  size="small"
                  label={label}
                  className={classes.compactLabel}
                  style={{
                    backgroundColor: tone.bg,
                    color: tone.fg,
                    border: `1px solid ${tone.bd}`,
                  }}
                />
              );
            })()
          ) : (
            <Chip
              size="small"
              label={FIX_LABELS[fix]}
              variant="outlined"
              className={classes.compactLabel}
            />
          )}
          <Typography className={classes.findingSubMsg} title={v.message}>
            {v.message}
          </Typography>
          <Typography className={classes.findingSubLoc}>
            {v.file}:{v.lineStart}
          </Typography>
        </Box>
        {remediationResult &&
          (inPr
            ? renderOutcomeDiff(v, 'accepted')
            : declined
              ? renderOutcomeDiff(v, 'declined')
              : (() => {
                  const lines = currentSnippetFor(v, quality.proposals);
                  if (!lines.length) return null;
                  return (
                    <Box className={classes.currentPreview}>
                      <Typography className={classes.currentPreviewTitle}>Current</Typography>
                      <Box className={classes.currentPreviewBody}>
                        {lines.map((line, i) => (
                          <Box key={`cur-${i}`} className={classes.currentPreviewLine}>
                            <span className={classes.currentPreviewLineNum}>
                              {(v.lineStart > 0 ? v.lineStart : 1) + i}
                            </span>
                            <span>{line || ' '}</span>
                          </Box>
                        ))}
                      </Box>
                    </Box>
                  );
                })())}
      </Box>
    );
  };

  const renderGroup = (group: FindingGroup) => {
    const open = expandedGroups.has(group.key);
    const kind = primaryKind(group.findings);
    const bySeverity = severityBreakdown(group.findings);
    const severityTip = bySeverity
      .map(x => `${x.sev.charAt(0).toUpperCase() + x.sev.slice(1)} ${x.count}`)
      .join(' · ');
    const currentLines = bestCurrentLines(group.findings, quality.proposals);
    const highlightFinding = activeKey
      ? group.findings.find(v => violationKey(v) === activeKey)
      : undefined;
    const lineBase =
      Math.min(...group.findings.map(v => (v.lineStart > 0 ? v.lineStart : 1))) || 1;

    return (
      <Box key={group.key} className={classes.nodeCard} role="listitem">
        <Box
          component="button"
          type="button"
          className={classes.nodeHeader}
          aria-expanded={open}
          onClick={() => toggleGroup(group.key)}
        >
          <span className={classes.nodeChevron} aria-hidden>
            {open ? <ExpandMoreIcon style={{ fontSize: 16 }} /> : <ChevronRightIcon style={{ fontSize: 16 }} />}
          </span>
          <Box className={classes.nodeMeta}>
            <Box className={classes.nodeIdentity}>
              <Typography className={classes.nodeTitle} title={group.title}>
                {group.title}
              </Typography>
              <Chip
                size="small"
                label={kindLabel(kind)}
                variant="outlined"
                className={classes.compactLabel}
              />
            </Box>
            <Box className={classes.nodeTrailing}>
              <Chip
                size="small"
                label={`${group.findings.length} finding${group.findings.length === 1 ? '' : 's'}`}
                variant="outlined"
                className={classes.compactLabel}
              />
              {bySeverity.length > 0 && (
                <Tooltip title={severityTip} arrow enterDelay={200}>
                  <Box
                    component="span"
                    className={classes.severityDots}
                    aria-label={`Severity breakdown: ${severityTip}`}
                  >
                    {bySeverity.map(({ sev, count }) => (
                      <span
                        key={sev}
                        className={classes.severityDot}
                        style={{ backgroundColor: SEVERITY_COLORS[sev] }}
                      >
                        {count}
                      </span>
                    ))}
                  </Box>
                </Tooltip>
              )}
            </Box>
          </Box>
        </Box>
        <Collapse in={open}>
          <Box className={classes.nodeDetail}>
            <Box className={classes.findingsDetail} role="list" aria-label="Findings at this location">
              {group.findings.map(v => renderFindingSubRow(v))}
            </Box>
            {/* Idle Assess: shared Current preview. Post-PR: Accepted rows show Before/After per finding. */}
            {!remediationResult && currentLines.length > 0 && (
              <Box className={classes.currentPreview}>
                <Typography className={classes.currentPreviewTitle}>Current</Typography>
                <Box className={classes.currentPreviewBody}>
                  {currentLines.map((line, i) => {
                    const lineNo = lineBase + i;
                    const highlighted =
                      highlightFinding != null &&
                      highlightFinding.lineStart > 0 &&
                      lineNo === highlightFinding.lineStart;
                    const findingKey = highlightFinding
                      ? violationKey(highlightFinding)
                      : null;
                    return (
                      <Box
                        key={`${group.key}-c-${i}`}
                        className={classes.currentPreviewLine}
                        ref={
                          highlighted && findingKey
                            ? (el: HTMLDivElement | null) => {
                                if (el) previewLineRefs.current.set(findingKey, el);
                                else previewLineRefs.current.delete(findingKey);
                              }
                            : undefined
                        }
                        style={{
                          backgroundColor: highlighted
                            ? (isDark ? 'rgba(43,154,243,0.22)' : 'rgba(0,102,204,0.1)')
                            : undefined,
                        }}
                      >
                        <span className={classes.currentPreviewLineNum}>{lineNo}</span>
                        <span>{line || ' '}</span>
                      </Box>
                    );
                  })}
                </Box>
              </Box>
            )}
          </Box>
        </Collapse>
      </Box>
    );
  };

  if (scan?.totalViolations === 0 || violations.length === 0) {
    return (
      <Box className={classes.root}>
        <ProvenanceHeader
          classes={classes}
          quality={quality}
          scanning={scanning}
          scanProgress={scanProgress}
          showResume={showResume}
          remediationResult={remediationResult}
          remainingCount={remainingCount}
          onScan={onScan}
          onViewHistory={onViewHistory}
          onRemediate={onRemediate}
          onResume={onResume}
        />
        <Box className={classes.emptyCard}>
          <CheckCircleIcon style={{ fontSize: 40, color: '#3E8635', marginBottom: 8 }} />
          <Typography style={{ fontSize: 16, fontWeight: 500 }}>No violations detected</Typography>
          <Typography style={{ fontSize: 13, color: theme.palette.text.secondary, marginTop: 4 }}>
            The latest quality scan found no issues in this repository.
          </Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box className={classes.root}>
      <ProvenanceHeader
        classes={classes}
        quality={quality}
        scanning={scanning}
        scanProgress={scanProgress}
        showResume={showResume}
        remediationResult={remediationResult}
        remainingCount={remainingCount}
        onScan={onScan}
        onViewHistory={onViewHistory}
        onRemediate={onRemediate}
        onResume={onResume}
      />

      {remediationResult && !scanning && (
        <Box className={classes.successBanner} role="status">
          <Box style={{ flex: 1, minWidth: 200 }}>
            <Typography style={{ fontSize: 13, fontWeight: 600, marginBottom: 2 }}>
              {hasOpenPr ? 'Pull request open' : 'Changes pushed'}
            </Typography>
            <Typography style={{ fontSize: 13 }}>
              {(() => {
                const parts = [
                  hasOpenPr
                    ? `${inPrCount} ${inPrCount === 1 ? 'fix' : 'fixes'} in the pull request`
                    : `${inPrCount} ${inPrCount === 1 ? 'fix' : 'fixes'} accepted on branch ${remediationResult.branchName}`,
                ];
                if (remainingCount > 0) {
                  parts.push(
                    `${remainingCount} remaining finding${remainingCount === 1 ? '' : 's'}`,
                  );
                }
                return remainingCount > 0
                  ? `${parts.join(' · ')}. Remediate remaining findings, or scan again after merge to refresh scores.`
                  : `${parts.join(' · ')}. Scan again after merge to refresh scores.`;
              })()}
            </Typography>
          </Box>
          <Box
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 8,
              flexShrink: 0,
              flexWrap: 'wrap',
            }}
          >
            {remainingCount > 0 && onRemediate && (
              <Button
                size="small"
                variant="contained"
                color="primary"
                onClick={onRemediate}
                style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500 }}
              >
                Remediate remaining
              </Button>
            )}
            {hasOpenPr && remediationResult.prUrl && (
              <Button
                size="small"
                variant="outlined"
                color="primary"
                href={remediationResult.prUrl}
                target="_blank"
                rel="noopener noreferrer"
                endIcon={<OpenInNewIcon style={{ fontSize: 14 }} />}
                style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500 }}
              >
                View pull request
              </Button>
            )}
            {hasOpenPr && (
              <Button
                size="small"
                color="primary"
                href={`/devspaces-mockup.html?state=pr&branch=${encodeURIComponent(
                  remediationResult.branchName,
                )}`}
                target="_blank"
                rel="noopener noreferrer"
                endIcon={<OpenInNewIcon style={{ fontSize: 14 }} />}
                style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500 }}
              >
                Review in Dev Spaces
              </Button>
            )}
          </Box>
        </Box>
      )}

      {showResume && !scanning && (
        <Box className={classes.resumeBanner}>
          <Box style={{ flex: 1, minWidth: 0 }}>
            <Typography style={{ fontSize: 13, fontWeight: 700, marginBottom: 4 }}>
              Remediation paused — resume to continue
            </Typography>
            <Typography style={{ fontSize: 13 }}>
              Resume where you left off. Starting over abandons this session and begins a new
              remediation from the latest scan.
            </Typography>
          </Box>
          <Box style={{ display: 'inline-flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
            {onRemediate && (
              <Button
                size="small"
                color="primary"
                onClick={onRemediate}
                style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500 }}
              >
                Start over
              </Button>
            )}
            <Button
              size="small"
              variant="contained"
              color="primary"
              onClick={onResume}
              style={{
                textTransform: 'none',
                borderRadius: 20,
                fontWeight: 600,
                minHeight: 36,
                paddingLeft: 16,
                paddingRight: 16,
              }}
            >
              Resume remediation
            </Button>
          </Box>
        </Box>
      )}

      {showStartRemediate && (
        <Box className={classes.resumeBanner}>
          <Box style={{ flex: 1, minWidth: 0 }}>
            <Typography style={{ fontSize: 13, fontWeight: 700, marginBottom: 4 }}>
              {violations.length} finding{violations.length === 1 ? '' : 's'} ready to remediate
            </Typography>
            <Typography style={{ fontSize: 13 }}>
              You&apos;ll review each suggestion and Accept or Decline before anything is applied.
            </Typography>
            <Typography
              style={{
                fontSize: 12,
                marginTop: 6,
                color: theme.palette.text.secondary,
                fontWeight: 500,
              }}
            >
              Path: Quick-fix → AI → Open pull request
            </Typography>
          </Box>
          <Button
            size="small"
            variant="contained"
            color="primary"
            onClick={onRemediate}
            style={{ textTransform: 'none', borderRadius: 20, fontWeight: 500, flexShrink: 0 }}
          >
            Start remediation
          </Button>
        </Box>
      )}

      {!remediationResult && (
      <Box className={classes.inventoryRow} role="group" aria-label="Findings inventory">
          {inventory.map(box => {
            const key = box.key as 'total' | FixType;
            // Default "all" (Total) stays quiet — only exclusive buckets look selected.
            const selected = key !== 'total' && exclusiveFixType === key;
            const disabled = key !== 'total' && box.primary === 0;
            const tip =
              key === 'total'
                ? fixNarrowed
                  ? 'Show all fix types'
                  : 'Showing all fix types'
                : selected
                  ? `Showing ${box.label} only — click again to show all`
                  : `Show ${box.label} findings only`;
            return (
              <Box
                key={box.key}
                role="button"
                tabIndex={disabled ? -1 : 0}
                aria-disabled={disabled}
                aria-pressed={selected}
                aria-label={`${box.label}. ${tip}`}
                onClick={() => {
                  if (!disabled) applyInventoryFixFilter(key);
                }}
                onKeyDown={e => {
                  if (disabled) return;
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault();
                    applyInventoryFixFilter(key);
                  }
                }}
                className={[
                  classes.inventoryBox,
                  classes.inventoryBoxButton,
                  selected ? classes.inventoryBoxSelected : '',
                  disabled ? classes.inventoryBoxDisabled : '',
                ]
                  .filter(Boolean)
                  .join(' ')}
              >
                <Typography className={classes.inventoryLabel} component="span">
                  {box.label}
                  <Tooltip title={INVENTORY_INFO[key]} arrow enterDelay={200}>
                    <Box
                      component="span"
                      role="img"
                      aria-label={INVENTORY_INFO[key]}
                      onClick={e => e.stopPropagation()}
                      onMouseDown={e => e.stopPropagation()}
                      onKeyDown={e => e.stopPropagation()}
                      style={{ display: 'inline-flex', lineHeight: 0 }}
                    >
                      <HelpOutlineIcon className={classes.inventoryInfoIcon} />
                    </Box>
                  </Tooltip>
                </Typography>
                <Typography className={classes.inventoryPrimary} style={{ color: box.tone }}>
                  {box.primary}
                </Typography>
                <Typography className={classes.inventorySecondary}>
                  {box.primary === 1 ? 'finding' : 'findings'} · {box.secondary}{' '}
                  {box.secondary === 1 ? 'location' : 'locations'}
                </Typography>
              </Box>
            );
          })}
      </Box>
      )}

      <Box className={classes.filterBar}>
        {remediationResult && (
          <Tabs
            value={outcomeFilter}
            onChange={(_, value: OutcomeFilter) => selectOutcomeFilter(value)}
            indicatorColor="primary"
            textColor="primary"
            variant="scrollable"
            scrollButtons="auto"
            className={classes.outcomeTabs}
            aria-label="Remediation outcome"
          >
            {(
              [
                { id: 'all' as const, label: 'All', count: violations.length },
                {
                  id: 'accepted' as const,
                  label: hasOpenPr ? 'Fixes in pull request' : 'Fixes accepted',
                  count: inPrCount,
                },
                {
                  id: 'remaining' as const,
                  label: 'Remaining findings',
                  count: remainingCount,
                },
              ] as const
            ).map(opt => (
              <Tab
                key={opt.id}
                value={opt.id}
                label={`${opt.label} (${opt.count})`}
                disableRipple
              />
            ))}
          </Tabs>
        )}

        {severityFacetTotal > 0 && (
          <Box className={classes.severityBar} role="group" aria-label="Severity distribution">
            {severityFacetOrder.map(sev => {
              const count = severityFacetCounts[sev];
              return (
                <Tooltip
                  key={sev}
                  title={`${SEVERITY_TOOLTIPS[sev]} (${count})`}
                  arrow
                  enterDelay={200}
                >
                  <Box
                    style={{
                      width: `${(count / severityFacetTotal) * 100}%`,
                      backgroundColor: SEVERITY_COLORS[sev],
                      // Full color when showing all; dim off segments only when narrowed.
                      opacity:
                        !severityNarrowed || severityFilters.has(sev) ? 1 : 0.25,
                      cursor: 'pointer',
                    }}
                    onClick={() => setSeverityFilters(prev => toggleInSet(prev, sev))}
                  />
                </Tooltip>
              );
            })}
          </Box>
        )}

        <Box className={classes.filterControls}>
          <Box className={classes.filterGroup} role="group" aria-label="Severity filters">
            {severityFacetOrder.map(sev => severityChip(sev, severityFilters.has(sev)))}
          </Box>

          <Box className={classes.filterMenus}>
          {!remediationResult && !showAdvancedFilters ? (
            <Button
              size="small"
              color="primary"
              onClick={() => setShowAdvancedFilters(true)}
              style={{ textTransform: 'none', fontSize: 12, minWidth: 0 }}
            >
              More filters
            </Button>
          ) : (
            <>
          <Tooltip
            arrow
            enterDelay={300}
            title="How findings are grouped in the list"
          >
            <Button
              size="small"
              variant="outlined"
              className={classes.filterMenuBtn}
              endIcon={<ArrowDropDownIcon style={{ marginLeft: -4 }} />}
              onClick={e => setViewMenuEl(e.currentTarget)}
              aria-haspopup="menu"
              aria-expanded={Boolean(viewMenuEl)}
            >
              View: {viewLabel}
            </Button>
          </Tooltip>
          <Menu
            anchorEl={viewMenuEl}
            open={Boolean(viewMenuEl)}
            onClose={() => setViewMenuEl(null)}
            getContentAnchorEl={null}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            transformOrigin={{ vertical: 'top', horizontal: 'left' }}
          >
            {VIEW_OPTIONS.map(opt => (
              <MenuItem
                key={opt.id}
                selected={viewMode === opt.id}
                onClick={() => {
                  setViewMode(opt.id);
                  setSelectedKey(null);
                  setHoverKey(null);
                  setViewMenuEl(null);
                }}
              >
                <ListItemText
                  primary={opt.label}
                  secondary={opt.hint}
                  primaryTypographyProps={{ style: { fontSize: 13 } }}
                  secondaryTypographyProps={{ style: { fontSize: 11 } }}
                />
              </MenuItem>
            ))}
          </Menu>

          <Button
            size="small"
            variant="outlined"
            className={`${classes.filterMenuBtn}${fixNarrowed ? ` ${classes.filterMenuBtnActive}` : ''}`}
            endIcon={<ArrowDropDownIcon style={{ marginLeft: -4 }} />}
            onClick={e => setFixMenuEl(e.currentTarget)}
            aria-haspopup="menu"
            aria-expanded={Boolean(fixMenuEl)}
          >
            {fixNarrowed ? `Fix type (${fixSelectedCount})` : 'Fix type'}
          </Button>
          <Menu
            anchorEl={fixMenuEl}
            open={Boolean(fixMenuEl)}
            onClose={() => setFixMenuEl(null)}
            getContentAnchorEl={null}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            transformOrigin={{ vertical: 'top', horizontal: 'left' }}
          >
            {presentFixTypes.map(({ type, count }) => {
              const checked = fixFilters.has(type);
              return (
                <MenuItem
                  key={type}
                  dense
                  onClick={() => setFixFilters(prev => toggleInSet(prev, type))}
                >
                  <Checkbox
                    size="small"
                    color="primary"
                    checked={checked}
                    tabIndex={-1}
                    disableRipple
                    style={{ padding: 4, marginRight: 4 }}
                  />
                  <ListItemText
                    primary={`${FIX_LABELS[type]} (${count})`}
                    primaryTypographyProps={{ style: { fontSize: 13 } }}
                  />
                </MenuItem>
              );
            })}
          </Menu>

          <Button
            size="small"
            variant="outlined"
            className={`${classes.filterMenuBtn}${kindNarrowed ? ` ${classes.filterMenuBtnActive}` : ''}`}
            endIcon={<ArrowDropDownIcon style={{ marginLeft: -4 }} />}
            onClick={e => setKindMenuEl(e.currentTarget)}
            aria-haspopup="menu"
            aria-expanded={Boolean(kindMenuEl)}
          >
            {kindNarrowed ? `Kind (${kindSelectedCount})` : 'Kind'}
          </Button>
          <Menu
            anchorEl={kindMenuEl}
            open={Boolean(kindMenuEl)}
            onClose={() => setKindMenuEl(null)}
            getContentAnchorEl={null}
            anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
            transformOrigin={{ vertical: 'top', horizontal: 'left' }}
          >
            {presentKinds.map(({ scope, count }) => {
              const checked = kindFilters.has(scope);
              return (
                <MenuItem
                  key={scope}
                  dense
                  onClick={() => setKindFilters(prev => toggleInSet(prev, scope))}
                >
                  <Checkbox
                    size="small"
                    color="primary"
                    checked={checked}
                    tabIndex={-1}
                    disableRipple
                    style={{ padding: 4, marginRight: 4 }}
                  />
                  <ListItemText
                    primary={`${kindLabel(scope)} (${count})`}
                    primaryTypographyProps={{ style: { fontSize: 13 } }}
                  />
                </MenuItem>
              );
            })}
          </Menu>
            </>
          )}
          </Box>
        </Box>
      </Box>

      <Box className={classes.listToolbar}>
        <Box style={{ display: 'inline-flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
          <Typography style={{ fontSize: 13, color: theme.palette.text.secondary }}>
            {filtered.length === facetByOutcome.length
              ? `${filtered.length} finding${filtered.length === 1 ? '' : 's'}`
              : `Showing ${filtered.length} of ${facetByOutcome.length} findings`}
          </Typography>
          {filtersActive && (
            <Button
              size="small"
              color="primary"
              onClick={clearAllFilters}
              style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 4px' }}
            >
              Clear all filters
            </Button>
          )}
          {groups.length > 0 && (
            <>
              <Button
                size="small"
                onClick={expandAll}
                style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 4px' }}
              >
                Expand all
              </Button>
              <Button
                size="small"
                onClick={collapseAll}
                style={{ textTransform: 'none', fontSize: 12, minWidth: 0, padding: '2px 4px' }}
              >
                Collapse all
              </Button>
            </>
          )}
        </Box>
      </Box>

      {filtered.length === 0 ? (
        <Box className={classes.emptyCard}>
          <Typography style={{ fontSize: 14, color: theme.palette.text.secondary }}>
            No findings match the current filters.
          </Typography>
          <Button
            size="small"
            color="primary"
            onClick={clearAllFilters}
            style={{ textTransform: 'none', marginTop: 8 }}
          >
            Clear all filters
          </Button>
        </Box>
      ) : (
        <Box
          role="list"
          aria-label={
            viewMode === 'by-location'
              ? 'Findings by location'
              : viewMode === 'by-file'
                ? 'Findings by file'
                : 'Findings (flat)'
          }
        >
          {groups.map(renderGroup)}
        </Box>
      )}
    </Box>
  );
}

function ProvenanceHeader({
  classes,
  quality,
  scanning,
  scanProgress,
  remediationResult,
  onScan,
  onViewHistory,
}: {
  classes: ReturnType<typeof useStyles>;
  quality: ProjectQualityData;
  scanning: boolean;
  scanProgress: number;
  showResume?: boolean;
  remediationResult?: RemediationFinishResult | null;
  remainingCount?: number;
  onScan: () => void;
  onViewHistory: () => void;
  onRemediate?: () => void;
  onResume?: () => void;
}) {
  const hasHistory = (quality.scanHistory?.length ?? 0) > 0;
  const triggerKey = quality.latestScan?.trigger ?? 'push';
  const triggerMeta = SCAN_TRIGGER_META[triggerKey] ?? SCAN_TRIGGER_META.push;
  /** Non-default triggers only — push is implied and stays in the Latest scan tip. */
  const triggerStrip: Record<string, string> = {
    pull_request: 'From a pull request',
    schedule: 'From a CI schedule',
    manual: 'Started in Portal',
  };
  const triggerStripLabel = triggerStrip[triggerKey];
  const scanHelpTitle =
    triggerKey === 'push'
      ? `${triggerMeta.tip} Quality scans analyze this repository for findings across syntax, security, compatibility, best practices, and dependency health. Scanning does not use AI.`
      : 'Quality scans analyze this repository for findings across syntax, security, compatibility, best practices, and dependency health. Scanning does not use AI. Scores refresh after you scan again.';

  return (
    <Box className={classes.provenance}>
      <Box style={{ minWidth: 0, flex: '1 1 280px' }}>
        {scanning ? (
          <>
            <Typography className={classes.metaSecondary}>Scanning repository…</Typography>
            <LinearProgress
              variant="determinate"
              value={scanProgress}
              style={{ height: 4, borderRadius: 2, marginTop: 10, maxWidth: 320 }}
            />
          </>
        ) : (
          <>
            <Typography
              className={classes.metaSecondary}
              component="div"
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 8,
                flexWrap: 'wrap',
              }}
            >
              <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                Latest scan
                <Tooltip title={scanHelpTitle} arrow>
                  <HelpOutlineIcon
                    style={{
                      fontSize: 13,
                      opacity: 0.55,
                      cursor: 'help',
                    }}
                  />
                </Tooltip>
              </span>
              <span aria-hidden>·</span>
              <span>{quality.lastScannedAt}</span>
              {quality.lastScannedCommit && (
                <>
                  <span aria-hidden>·</span>
                  <span>
                    Commit{' '}
                    <code className={classes.commitCode}>{quality.lastScannedCommit}</code>
                  </span>
                </>
              )}
              {triggerStripLabel && (
                <>
                  <span aria-hidden>·</span>
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
                    {triggerStripLabel}
                    <Tooltip title={triggerMeta.tip} arrow enterDelay={200}>
                      <Box
                        component="span"
                        role="img"
                        aria-label={triggerMeta.tip}
                        style={{ display: 'inline-flex', lineHeight: 0 }}
                      >
                        <HelpOutlineIcon
                          style={{
                            fontSize: 13,
                            opacity: 0.55,
                            cursor: 'help',
                          }}
                        />
                      </Box>
                    </Tooltip>
                  </span>
                </>
              )}
              {!remediationResult && (
                <>
                  <span aria-hidden>·</span>
                  <span>Pending remediation</span>
                </>
              )}
            </Typography>
          </>
        )}
      </Box>

      <Box className={classes.actions}>
        {hasHistory && !scanning && (
          <Button
            size="small"
            color="primary"
            onClick={onViewHistory}
            style={{ textTransform: 'none', fontSize: 13 }}
          >
            View scan history
          </Button>
        )}
        <Tooltip title="Runs a quality scan — no AI, no usage costs" arrow>
          <span>
            <Button
              size="small"
              variant="outlined"
              color="primary"
              aria-label={scanning ? 'Scanning repository' : 'Scan again'}
              startIcon={
                <AutorenewIcon
                  style={{ fontSize: 14 }}
                  className={scanning ? classes.spinIcon : undefined}
                  aria-hidden
                />
              }
              disabled={scanning}
              onClick={onScan}
              style={{ textTransform: 'none', fontSize: 12, borderRadius: 20 }}
            >
              {scanning ? 'Scanning…' : 'Scan again'}
            </Button>
          </span>
        </Tooltip>
      </Box>
    </Box>
  );
}
